The following Verilog code implements an APB clock-domain bridge:

```
module apbxclk #(
		parameter	C_APB_ADDR_WIDTH = 12,
		parameter	C_APB_DATA_WIDTH = 32,
		parameter [0:0]	OPT_REGISTERED = 1'b0,
		localparam	AW = C_APB_ADDR_WIDTH,
		localparam	DW = C_APB_DATA_WIDTH
	) (
		input	wire			S_APB_PCLK, S_PRESETn,
		input	wire			S_APB_PSEL,
		input	wire			S_APB_PENABLE,
		output	reg			S_APB_PREADY,
		input	wire	[AW-1:0]	S_APB_PADDR,
		input	wire			S_APB_PWRITE,
		input	wire	[DW-1:0]	S_APB_PWDATA,
		input	wire	[DW/8-1:0]	S_APB_PWSTRB,
		input	wire	[2:0]		S_APB_PPROT,
		output	wire	[DW-1:0]	S_APB_PRDATA,
		output	wire			S_APB_PSLVERR,
		input	wire			M_APB_PCLK,
		output	reg			M_PRESETn,
		output	reg			M_APB_PSEL,
		output	reg			M_APB_PENABLE,
		input	wire			M_APB_PREADY,
		output	wire	[AW-1:0]	M_APB_PADDR,
		output	wire			M_APB_PWRITE,
		output	wire	[DW-1:0]	M_APB_PWDATA,
		output	wire	[DW/8-1:0]	M_APB_PWSTRB,
		output	wire	[2:0]		M_APB_PPROT,
		input	wire	[DW-1:0]	M_APB_PRDATA,
		input	wire			M_APB_PSLVERR
	);

	// Internal signals
	reg [AW-1:0] addr_reg;
	reg [DW-1:0] wdata_reg;
	reg [DW/8-1:0] wstrb_reg;
	reg [2:0] prot_reg;
	reg write_reg;
	reg sel_reg;
	reg enable_reg;
	reg [DW-1:0] rdata_reg;
	reg sslverr_reg;
	reg sready_reg;

	// Register crossing
	always @(posedge S_APB_PCLK) begin
		if (!S_PRESETn) begin
			addr_reg <= 0;
			wdata_reg <= 0;
			wstrb_reg <= 0;
			prot_reg <= 0;
			write_reg <= 0;
			sel_reg <= 0;
			enable_reg <= 0;
			rdata_reg <= 0;
			sslverr_reg <= 0;
			sready_reg <= 0;
		end else begin
			if (OPT_REGISTERED) begin
				addr_reg <= S_APB_PADDR;
				wdata_reg <= S_APB_PWDATA;
				wstrb_reg <= S_APB_PWSTRB;
				prot_reg <= S_APB_PPROT;
				write_reg <= S_APB_PWRITE;
				sel_reg <= S_APB_PSEL;
				enable_reg <= S_APB_PENABLE;
				rdata_reg <= M_APB_PRDATA;
				sslverr_reg <= M_APB_PSLVERR;
				sready_reg <= M_APB_PREADY;
			end else begin
				addr_reg <= S_APB_PADDR;
				wdata_reg <= S_APB_PWDATA;
				wstrb_reg <= S_APB_PWSTRB;
				prot_reg <= S_APB_PPROT;
				write_reg <= S_APB_PWRITE;
				sel_reg <= S_APB_PSEL;
				enable_reg <= S_APB_PENABLE;
				rdata_reg <= M_APB_PRDATA;
				sslverr_reg <= M_APB_PSLVERR;
				sready_reg <= M_APB_PREADY;
			end
		end
	end

	// APB transfer
	always @(posedge S_APB_PCLK) begin
		if (!S_PRESETn) begin
			S_APB_PREADY <= 0;
			M_PRESETn <= 0;
			M_APB_PSEL <= 0;
			M_APB_PENABLE <= 0;
			M_APB_PADDR <= 0;
			M_APB_PWRITE <= 0;
			M_APB_PWDATA <= 0;
			M_APB_PWSTRB <= 0;
			M_APB_PPROT <= 0;
		end else begin
			if (sel_reg && enable_reg) begin
				S_APB_PREADY <= 0;
				M_PRESETn <= 0;
				M_APB_PSEL <= 1;
				M_APB_PENABLE <= 1;
				M_APB_PADDR <= addr_reg;
				M_APB_PWRITE <= write_reg;
				M_APB_PWDATA <= wdata_reg;
				M_APB_PWSTRB <= wstrb_reg;
				M_APB_PPROT <= prot_reg;
			end else begin
				S_APB_PREADY <= sready_reg;
				M_PRESETn <= 1;
				M_APB_PSEL <= 0;
				M_APB_PENABLE <= 0;
				M_APB_PADDR <= 0;
				M_APB_PWRITE <= 0;
				M_APB_PWDATA <= 0;
				M_APB_PWSTRB <= 0;
				M_APB_PPROT <= 0;
			end
		end
	end

	// Return read data and slave-error status to the source interface
	assign S_APB_PRDATA = rdata_reg;
	assign S_APB_PSLVERR = sslverr_reg;

